_ADDER_SUB_7SEG_SV = Template(
    """// Auto-generated by fpga_autopilot — Strict Synthesizable SystemVerilog-2012
// Zero inferred latches, pure combinational arithmetic + dual active-low 7-seg decoder

module {{ top_module }} (
    input  logic signed [3:0] a,
    input  logic signed [3:0] b,
    input  logic              sub_mode,
    output logic signed [3:0] result,
    output logic              cout,
    output logic              overflow,
    output logic              zero,
    output logic        [6:0] seg_sign,
    output logic        [6:0] seg_mag
);

    logic [3:0] a_u;
    logic [3:0] b_eff;
    logic [4:0] sum_ext;
    logic [3:0] mag;

    always_comb begin
        // Explicit default assignments guarantee 0 inferred latches
        a_u      = 4'd0;
        b_eff    = 4'd0;
        sum_ext  = 5'd0;
        result   = 4'sd0;
        cout     = 1'b0;
        overflow = 1'b0;
        zero     = 1'b0;
        mag      = 4'd0;
        seg_sign = 7'b111_1111;
        seg_mag  = 7'b111_1111;

        a_u      = a[3:0];
        b_eff    = b[3:0] ^ {4{sub_mode}};
        sum_ext  = {1'b0, a_u} + {1'b0, b_eff} + {4'b0000, sub_mode};

        result   = $signed(sum_ext[3:0]);
        cout     = sum_ext[4];
        overflow = (a_u[3] == b_eff[3]) && (sum_ext[3] != a_u[3]);
        zero     = (sum_ext[3:0] == 4'd0);

        if (sum_ext[3]) begin
            seg_sign = 7'b011_1111; // '-' on segment g (active-low)
            mag      = (~sum_ext[3:0]) + 4'd1;
        end else begin
            seg_sign = 7'b111_1111; // blank when >= 0 (active-low)
            mag      = sum_ext[3:0];
        end

        case (mag)
            4'h0:    seg_mag = 7'b100_0000;
            4'h1:    seg_mag = 7'b111_1001;
            4'h2:    seg_mag = 7'b010_0100;
            4'h3:    seg_mag = 7'b011_0000;
            4'h4:    seg_mag = 7'b001_1001;
            4'h5:    seg_mag = 7'b001_0010;
            4'h6:    seg_mag = 7'b000_0010;
            4'h7:    seg_mag = 7'b111_1000;
            4'h8:    seg_mag = 7'b000_0000;
            4'h9:    seg_mag = 7'b001_0000;
            4'hA:    seg_mag = 7'b000_1000;
            4'hB:    seg_mag = 7'b000_0011;
            4'hC:    seg_mag = 7'b100_0110;
            4'hD:    seg_mag = 7'b010_0001;
            4'hE:    seg_mag = 7'b000_0110;
            4'hF:    seg_mag = 7'b000_1110;
            default: seg_mag = 7'b111_1111;
        endcase
    end

endmodule
"""
)

_TRAFFIC_FSM_SV = Template(
    """// Auto-generated by fpga_autopilot — Strict Synthesizable SystemVerilog-2012
// Parameterized tick divider + 2-FF synchronizer + debouncer + Moore Traffic FSM

module {{ top_module }} #(
    parameter [31:0] SIM_MODE          = 32'd{{ sim_mode }},
    parameter [31:0] CLK_FREQ_HZ       = 32'd{{ clk_freq_hz }},
    parameter [31:0] SIM_TICKS_PER_SEC = 32'd{{ sim_ticks_per_sec }},
    parameter [3:0]  GREEN_SEC         = 4'd{{ green_sec }},
    parameter [3:0]  YELLOW_SEC        = 4'd{{ yellow_sec }},
    parameter [3:0]  PED_SEC           = 4'd{{ ped_sec }},
    parameter [3:0]  ALL_RED_SEC       = 4'd{{ all_red_sec }}
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       ped_btn_raw,
    input  logic       emergency_ovr,
    output logic [2:0] ns_light,
    output logic [2:0] ew_light,
    output logic       ped_walk,
    output logic [3:0] countdown
);

    typedef enum logic [2:0] {
        ST_NS_GREEN  = 3'd0,
        ST_NS_YELLOW = 3'd1,
        ST_ALL_RED_1 = 3'd2,
        ST_EW_GREEN  = 3'd3,
        ST_EW_YELLOW = 3'd4,
        ST_ALL_RED_2 = 3'd5,
        ST_PED_WALK  = 3'd6,
        ST_EMERGENCY = 3'd7
    } state_t;

    localparam [31:0] TICKS_PER_SEC = (SIM_MODE != 32'd0) ? SIM_TICKS_PER_SEC : CLK_FREQ_HZ;
    localparam [31:0] DEBOUNCE_MAX  = (SIM_MODE != 32'd0) ? 32'd2 : (CLK_FREQ_HZ / 32'd100);

    localparam [2:0] LIGHT_RED    = 3'b100;
    localparam [2:0] LIGHT_YELLOW = 3'b010;
    localparam [2:0] LIGHT_GREEN  = 3'b001;

    state_t      state, next_state;
    logic [31:0] tick_cnt;
    logic        sec_tick;
    logic        phase_done;
    logic [3:0]  timer_sec;
    logic [3:0]  next_duration;

    // 2-FF synchronizer + debouncer for asynchronous pedestrian button
    logic        ped_sync_ff1;
    logic        ped_sync_ff2;
    logic [31:0] db_cnt;
    logic        ped_debounced;
    logic        ped_debounced_d;
    logic        ped_pulse;
    logic        ped_pending;
    logic        resume_to_ew;

    // 2-FF Synchronizer & Counter-Based Debouncer
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ped_sync_ff1    <= 1'b0;
            ped_sync_ff2    <= 1'b0;
            db_cnt          <= 32'd0;
            ped_debounced   <= 1'b0;
            ped_debounced_d <= 1'b0;
        end else begin
            ped_sync_ff1    <= ped_btn_raw;
            ped_sync_ff2    <= ped_sync_ff1;
            ped_debounced_d <= ped_debounced;

            if (ped_sync_ff2 == ped_debounced) begin
                db_cnt <= 32'd0;
            end else if (db_cnt >= (DEBOUNCE_MAX - 32'd1)) begin
                db_cnt        <= 32'd0;
                ped_debounced <= ped_sync_ff2;
            end else begin
                db_cnt <= db_cnt + 32'd1;
            end
        end
    end

    always_comb begin
        ped_pulse  = 1'b0;
        sec_tick   = 1'b0;
        phase_done = 1'b0;

        ped_pulse  = ped_debounced && !ped_debounced_d;
        sec_tick   = (tick_cnt == (TICKS_PER_SEC - 32'd1));
        phase_done = sec_tick && (timer_sec <= 4'd1);
    end

    // Pedestrian Request Latch & Fair Direction Resume Memory
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ped_pending  <= 1'b0;
            resume_to_ew <= 1'b1;
        end else begin
            if (emergency_ovr || (state == ST_PED_WALK)) begin
                ped_pending <= 1'b0;
            end else if (ped_pulse || ped_debounced) begin
                ped_pending <= 1'b1;
            end

            if (state == ST_ALL_RED_1) begin
                resume_to_ew <= 1'b1;
            end else if (state == ST_ALL_RED_2) begin
                resume_to_ew <= 1'b0;
            end
        end
    end

    // FSM State Register
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= ST_NS_GREEN;
        end else begin
            state <= next_state;
        end
    end

    // Parameterized Tick Generator & Countdown Timer
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tick_cnt  <= 32'd0;
            timer_sec <= GREEN_SEC;
        end else if (emergency_ovr) begin
            tick_cnt  <= 32'd0;
            timer_sec <= 4'd0;
        end else if (state != next_state) begin
            tick_cnt  <= 32'd0;
            timer_sec <= next_duration;
        end else if (sec_tick) begin
            tick_cnt <= 32'd0;
            if (timer_sec > 4'd1) begin
                timer_sec <= timer_sec - 4'd1;
            end
        end else begin
            tick_cnt <= tick_cnt + 32'd1;
        end
    end

    // Next-State & Next-Phase-Duration Combinational Logic
    always_comb begin
        next_state    = state;
        next_duration = GREEN_SEC;

        if (emergency_ovr) begin
            next_state    = ST_EMERGENCY;
            next_duration = 4'd0;
        end else begin
            case (state)
                ST_NS_GREEN: begin
                    if (phase_done) begin
                        next_state    = ST_NS_YELLOW;
                        next_duration = YELLOW_SEC;
                    end
                end
                ST_NS_YELLOW: begin
                    if (phase_done) begin
                        next_state    = ST_ALL_RED_1;
                        next_duration = ALL_RED_SEC;
                    end
                end
                ST_ALL_RED_1: begin
                    if (phase_done) begin
                        if (ped_pending) begin
                            next_state    = ST_PED_WALK;
                            next_duration = PED_SEC;
                        end else begin
                            next_state    = ST_EW_GREEN;
                            next_duration = GREEN_SEC;
                        end
                    end
                end
                ST_EW_GREEN: begin
                    if (phase_done) begin
                        next_state    = ST_EW_YELLOW;
                        next_duration = YELLOW_SEC;
                    end
                end
                ST_EW_YELLOW: begin
                    if (phase_done) begin
                        next_state    = ST_ALL_RED_2;
                        next_duration = ALL_RED_SEC;
                    end
                end
                ST_ALL_RED_2: begin
                    if (phase_done) begin
                        if (ped_pending) begin
                            next_state    = ST_PED_WALK;
                            next_duration = PED_SEC;
                        end else begin
                            next_state    = ST_NS_GREEN;
                            next_duration = GREEN_SEC;
                        end
                    end
                end
                ST_PED_WALK: begin
                    if (phase_done) begin
                        if (resume_to_ew) begin
                            next_state    = ST_EW_GREEN;
                            next_duration = GREEN_SEC;
                        end else begin
                            next_state    = ST_NS_GREEN;
                            next_duration = GREEN_SEC;
                        end
                    end
                end
                ST_EMERGENCY: begin
                    next_state    = ST_ALL_RED_1;
                    next_duration = ALL_RED_SEC;
                end
                default: begin
                    next_state    = ST_NS_GREEN;
                    next_duration = GREEN_SEC;
                end
            endcase
        end
    end

    // Glitch-Free Pure Moore Output Logic
    always_comb begin
        ns_light  = LIGHT_RED;
        ew_light  = LIGHT_RED;
        ped_walk  = 1'b0;
        countdown = timer_sec;

        case (state)
            ST_NS_GREEN: begin
                ns_light = LIGHT_GREEN;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_NS_YELLOW: begin
                ns_light = LIGHT_YELLOW;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_ALL_RED_1: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_EW_GREEN: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_GREEN;
                ped_walk = 1'b0;
            end
            ST_EW_YELLOW: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_YELLOW;
                ped_walk = 1'b0;
            end
            ST_ALL_RED_2: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_PED_WALK: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_RED;
                ped_walk = 1'b1;
            end
            ST_EMERGENCY: begin
                ns_light  = LIGHT_RED;
                ew_light  = LIGHT_RED;
                ped_walk  = 1'b0;
                countdown = 4'd0;
            end
            default: begin
                ns_light  = LIGHT_RED;
                ew_light  = LIGHT_RED;
                ped_walk  = 1'b0;
                countdown = 4'd0;
            end
        endcase
    end

endmodule
"""
)

_SYNC_FIFO_SV = """// Auto-generated by fpga_autopilot — Parameterized Show-Ahead Circular Sync FIFO

module sync_fifo #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 3
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  wr_en,
    input  logic [DATA_WIDTH-1:0] wr_data,
    input  logic                  rd_en,
    output logic [DATA_WIDTH-1:0] rd_data,
    output logic                  full,
    output logic                  empty
);

    localparam DEPTH = (1 << ADDR_WIDTH);
    localparam [ADDR_WIDTH:0] FULL_COUNT  = {1'b1, {ADDR_WIDTH{1'b0}}};
    localparam [ADDR_WIDTH:0] EMPTY_COUNT = {(ADDR_WIDTH + 1){1'b0}};
    localparam [ADDR_WIDTH:0] ONE_COUNT   = {{ADDR_WIDTH{1'b0}}, 1'b1};
    localparam [ADDR_WIDTH-1:0] ONE_PTR   = {{(ADDR_WIDTH - 1){1'b0}}, 1'b1};

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];
    logic [ADDR_WIDTH-1:0] wr_ptr;
    logic [ADDR_WIDTH-1:0] rd_ptr;
    logic [ADDR_WIDTH:0]   count;
    logic                  do_wr;
    logic                  do_rd;

    always_comb begin
        full    = (count == FULL_COUNT);
        empty   = (count == EMPTY_COUNT);
        rd_data = mem[rd_ptr];
    end

    always_comb begin
        do_wr = wr_en && !full;
        do_rd = rd_en && !empty;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= {ADDR_WIDTH{1'b0}};
            rd_ptr <= {ADDR_WIDTH{1'b0}};
            count  <= EMPTY_COUNT;
            for (int idx = 0; idx < DEPTH; idx = idx + 1) begin
                mem[idx] <= {DATA_WIDTH{1'b0}};
            end
        end else begin
            if (do_wr) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= wr_ptr + ONE_PTR;
            end
            if (do_rd) begin
                rd_ptr <= rd_ptr + ONE_PTR;
            end
            case ({do_wr, do_rd})
                2'b10:   count <= count + ONE_COUNT;
                2'b01:   count <= count - ONE_COUNT;
                default: count <= count;
            endcase
        end
    end

endmodule
"""

_UART_TX_SV = """// Auto-generated by fpga_autopilot — UART Transmitter FSM (8N1)

module uart_tx #(
    parameter [31:0] BIT_CLKS = 32'd432
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       fifo_empty,
    input  logic [7:0] fifo_data,
    output logic       fifo_pop,
    output logic       tx_serial,
    output logic       tx_busy
);

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_START = 2'd1,
        TX_DATA  = 2'd2,
        TX_STOP  = 2'd3
    } tx_state_t;

    tx_state_t   state, next_state;
    logic [31:0] clk_cnt;
    logic        bit_done;
    logic [2:0]  bit_idx;
    logic [7:0]  shift_reg;

    always_comb begin
        fifo_pop   = 1'b0;
        tx_serial  = 1'b1;
        tx_busy    = 1'b1;
        next_state = state;
        bit_done   = (clk_cnt == (BIT_CLKS - 32'd1));

        case (state)
            TX_IDLE: begin
                tx_serial = 1'b1;
                tx_busy   = 1'b0;
                if (!fifo_empty) begin
                    fifo_pop   = 1'b1;
                    next_state = TX_START;
                end
            end
            TX_START: begin
                tx_serial = 1'b0;
                tx_busy   = 1'b1;
                if (bit_done) begin
                    next_state = TX_DATA;
                end
            end
            TX_DATA: begin
                tx_serial = shift_reg[0];
                tx_busy   = 1'b1;
                if (bit_done && (bit_idx == 3'd7)) begin
                    next_state = TX_STOP;
                end
            end
            TX_STOP: begin
                tx_serial = 1'b1;
                tx_busy   = 1'b1;
                if (bit_done) begin
                    next_state = TX_IDLE;
                end
            end
            default: begin
                tx_serial  = 1'b1;
                tx_busy    = 1'b0;
                next_state = TX_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= TX_IDLE;
            clk_cnt   <= 32'd0;
            bit_idx   <= 3'd0;
            shift_reg <= 8'd0;
        end else begin
            state <= next_state;
            case (state)
                TX_IDLE: begin
                    clk_cnt <= 32'd0;
                    bit_idx <= 3'd0;
                    if (!fifo_empty) begin
                        shift_reg <= fifo_data;
                    end
                end
                TX_START: begin
                    if (bit_done) begin
                        clk_cnt <= 32'd0;
                        bit_idx <= 3'd0;
                    end else begin
                        clk_cnt <= clk_cnt + 32'd1;
                    end
                end
                TX_DATA: begin
                    if (bit_done) begin
                        clk_cnt   <= 32'd0;
                        shift_reg <= {1'b0, shift_reg[7:1]};
                        if (bit_idx != 3'd7) begin
                            bit_idx <= bit_idx + 3'd1;
                        end
                    end else begin
                        clk_cnt <= clk_cnt + 32'd1;
                    end
                end
                TX_STOP: begin
                    if (bit_done) begin
                        clk_cnt <= 32'd0;
                    end else begin
                        clk_cnt <= clk_cnt + 32'd1;
                    end
                end
                default: begin
                    clk_cnt <= 32'd0;
                end
            endcase
        end
    end

endmodule
"""

_UART_RX_SV = """// Auto-generated by fpga_autopilot — UART Receiver FSM with 16x Oversampling

module uart_rx #(
    parameter [31:0] OS_DIV = 32'd27
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       rx_serial,
    input  logic       clr_err,
    output logic       rx_valid,
    output logic [7:0] rx_byte,
    output logic       framing_error
);

    typedef enum logic [2:0] {
        RX_IDLE     = 3'd0,
        RX_START    = 3'd1,
        RX_DATA     = 3'd2,
        RX_STOP     = 3'd3,
        RX_ERR_WAIT = 3'd4
    } rx_state_t;

    rx_state_t   state, next_state;
    logic        rx_ff1;
    logic        rx_sync;
    logic [31:0] div_cnt;
    logic        os_tick;
    logic [3:0]  os_cnt;
    logic [2:0]  bit_idx;
    logic [7:0]  shift_reg;

    // 2-FF input synchronizer (idle UART line is logic HIGH)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_ff1  <= 1'b1;
            rx_sync <= 1'b1;
        end else begin
            rx_ff1  <= rx_serial;
            rx_sync <= rx_ff1;
        end
    end

    always_comb begin
        os_tick    = 1'b0;
        next_state = state;

        os_tick = (div_cnt == (OS_DIV - 32'd1));

        case (state)
            RX_IDLE: begin
                if (!rx_sync) begin
                    next_state = RX_START;
                end
            end
            RX_START: begin
                if (os_tick && (os_cnt == 4'd7)) begin
                    if (!rx_sync) begin
                        next_state = RX_DATA;
                    end else begin
                        next_state = RX_IDLE;
                    end
                end
            end
            RX_DATA: begin
                if (os_tick && (os_cnt == 4'd15) && (bit_idx == 3'd7)) begin
                    next_state = RX_STOP;
                end
            end
            RX_STOP: begin
                if (os_tick && (os_cnt == 4'd15)) begin
                    if (rx_sync) begin
                        next_state = RX_IDLE;
                    end else begin
                        next_state = RX_ERR_WAIT;
                    end
                end
            end
            RX_ERR_WAIT: begin
                if (rx_sync) begin
                    next_state = RX_IDLE;
                end
            end
            default: begin
                next_state = RX_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state         <= RX_IDLE;
            div_cnt       <= 32'd0;
            os_cnt        <= 4'd0;
            bit_idx       <= 3'd0;
            shift_reg     <= 8'd0;
            rx_byte       <= 8'd0;
            rx_valid      <= 1'b0;
            framing_error <= 1'b0;
        end else begin
            state    <= next_state;
            rx_valid <= 1'b0;

            if (clr_err) begin
                framing_error <= 1'b0;
            end

            case (state)
                RX_IDLE: begin
                    div_cnt <= 32'd0;
                    os_cnt  <= 4'd0;
                    bit_idx <= 3'd0;
                end
                RX_START: begin
                    if (os_tick) begin
                        div_cnt <= 32'd0;
                        if (os_cnt == 4'd7) begin
                            os_cnt <= 4'd0;
                        end else begin
                            os_cnt <= os_cnt + 4'd1;
                        end
                    end else begin
                        div_cnt <= div_cnt + 32'd1;
                    end
                end
                RX_DATA: begin
                    if (os_tick) begin
                        div_cnt <= 32'd0;
                        if (os_cnt == 4'd15) begin
                            os_cnt    <= 4'd0;
                            shift_reg <= {rx_sync, shift_reg[7:1]};
                            if (bit_idx != 3'd7) begin
                                bit_idx <= bit_idx + 3'd1;
                            end
                        end else begin
                            os_cnt <= os_cnt + 4'd1;
                        end
                    end else begin
                        div_cnt <= div_cnt + 32'd1;
                    end
                end
                RX_STOP: begin
                    if (os_tick) begin
                        div_cnt <= 32'd0;
                        if (os_cnt == 4'd15) begin
                            os_cnt <= 4'd0;
                            if (rx_sync) begin
                                rx_byte  <= shift_reg;
                                rx_valid <= 1'b1;
                            end else begin
                                framing_error <= 1'b1;
                            end
                        end else begin
                            os_cnt <= os_cnt + 4'd1;
                        end
                    end else begin
                        div_cnt <= div_cnt + 32'd1;
                    end
                end
                RX_ERR_WAIT: begin
                    div_cnt <= 32'd0;
                    os_cnt  <= 4'd0;
                end
                default: begin
                    div_cnt <= 32'd0;
                    os_cnt  <= 4'd0;
                end
            endcase
        end
    end

endmodule
"""

_UART_FIFO_TOP_SV = Template(
    """// Auto-generated by fpga_autopilot — Configurable UART TX/RX Transceiver + 8-Byte Sync FIFOs

module {{ top_module }} #(
    parameter [31:0] CLK_FREQ  = 32'd{{ clk_freq }},
    parameter [31:0] BAUD_RATE = 32'd{{ baud_rate }}
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       wr_en,
    input  logic [7:0] wr_data,
    input  logic       rd_en,
    input  logic       rx_serial,
    input  logic       clr_err,
    output logic       tx_serial,
    output logic [7:0] rd_data,
    output logic       tx_full,
    output logic       tx_empty,
    output logic       rx_full,
    output logic       rx_empty,
    output logic       tx_busy,
    output logic       framing_error
);

    localparam [31:0] OS_DIV_RAW = CLK_FREQ / (BAUD_RATE * 32'd16);
    localparam [31:0] OS_DIV     = (OS_DIV_RAW == 32'd0) ? 32'd1 : OS_DIV_RAW;
    localparam [31:0] BIT_CLKS   = OS_DIV * 32'd16;

    logic [7:0] tx_fifo_dout;
    logic       tx_fifo_pop;
    logic       rx_valid;
    logic [7:0] rx_byte;
    logic       rx_fifo_wr;

    always_comb begin
        rx_fifo_wr = rx_valid && !rx_full;
    end

    sync_fifo #(
        .DATA_WIDTH (8),
        .ADDR_WIDTH (3)
    ) u_tx_fifo (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .rd_en   (tx_fifo_pop),
        .rd_data (tx_fifo_dout),
        .full    (tx_full),
        .empty   (tx_empty)
    );

    uart_tx #(
        .BIT_CLKS (BIT_CLKS)
    ) u_uart_tx (
        .clk        (clk),
        .rst_n      (rst_n),
        .fifo_empty (tx_empty),
        .fifo_data  (tx_fifo_dout),
        .fifo_pop   (tx_fifo_pop),
        .tx_serial  (tx_serial),
        .tx_busy    (tx_busy)
    );

    uart_rx #(
        .OS_DIV (OS_DIV)
    ) u_uart_rx (
        .clk           (clk),
        .rst_n         (rst_n),
        .rx_serial     (rx_serial),
        .clr_err       (clr_err),
        .rx_valid      (rx_valid),
        .rx_byte       (rx_byte),
        .framing_error (framing_error)
    );

    sync_fifo #(
        .DATA_WIDTH (8),
        .ADDR_WIDTH (3)
    ) u_rx_fifo (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (rx_fifo_wr),
        .wr_data (rx_byte),
        .rd_en   (rd_en),
        .rd_data (rd_data),
        .full    (rx_full),
        .empty   (rx_empty)
    );

endmodule
"""
)


def _param_dict(spec: DigitalSpec) -> dict[str, int | str]:
    return {p.name: p.default_value for p in spec.parameters}


def default_llm_synthesis_hook(
    spec: DigitalSpec, prompt_context: str | None = None
) -> dict[str, str] | None:
    """Optional external LLM synthesis hook when FPGA_AUTOPILOT_LLM_ENDPOINT is configured."""
    endpoint = os.environ.get("FPGA_AUTOPILOT_LLM_ENDPOINT")
    api_key = os.environ.get("FPGA_AUTOPILOT_LLM_API_KEY", "")
    if not endpoint:
        return None

    payload = {
        "spec": spec.model_dump(),
        "prompt_context": prompt_context or "",
        "rules": [
            "SystemVerilog-2012 only: logic, always_ff @(posedge clk or negedge rst_n), always_comb",
            "Explicit default assignments at top of every always_comb block (0 latches)",
            "Non-blocking (<=) in always_ff, blocking (=) in always_comb",
        ],
    }
    req = urllib.request.Request(
        endpoint,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            **({"Authorization": f"Bearer {api_key}"} if api_key else {}),
        },
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=30) as resp:  # noqa: S310
        data = json.loads(resp.read().decode("utf-8"))
        if isinstance(data, dict) and "files" in data:
            return dict(data["files"])
    return None


def _render_generic_sync_sv(spec: DigitalSpec) -> str:
    """Fallback synthesizable template for arbitrary synchronous/combinational specs."""
    top = spec.top_module or spec.name
    port_lines = [p.sv_decl(is_last=(i == len(spec.ports) - 1)) for i, p in enumerate(spec.ports)]
    inputs = [
        p
        for p in spec.ports
        if p.direction == "input" and p.name not in {spec.clock_port, spec.reset_port}
    ]
    outputs = [p for p in spec.ports if p.direction == "output"]

    lines = [
        "// Auto-generated by fpga_autopilot — Generic Synthesizable SystemVerilog Module",
        f"module {top} (",
        *port_lines,
        ");",
        "",
    ]

    if spec.clock_port and spec.reset_port:
        rst_edge = f"negedge {spec.reset_port}" if spec.reset_active_low else f"posedge {spec.reset_port}"
        rst_cond = f"!{spec.reset_port}" if spec.reset_active_low else spec.reset_port
        for out_p in outputs:
            w = out_p.width
            lines.append(f"    logic [{w - 1}:0] {out_p.name}_next;" if w > 1 else f"    logic {out_p.name}_next;")
        lines.append("")
        lines.append("    always_comb begin")
        for idx, out_p in enumerate(outputs):
            w = out_p.width
            lines.append(f"        {out_p.name}_next = {w}'d0;")
            if inputs:
                src = inputs[idx % len(inputs)]
                if src.width == w:
                    lines.append(f"        {out_p.name}_next = {src.name};")
                elif src.width > w:
                    lines.append(f"        {out_p.name}_next = {src.name}[{w - 1}:0];")
                else:
                    pad = w - src.width
                    lines.append(f"        {out_p.name}_next = {{{pad}'d0, {src.name}}};")
        lines.append("    end")
        lines.append("")
        lines.append(f"    always_ff @(posedge {spec.clock_port} or {rst_edge}) begin")
        lines.append(f"        if ({rst_cond}) begin")
        for out_p in outputs:
            lines.append(f"            {out_p.name} <= {out_p.width}'d0;")
        lines.append("        end else begin")
        for out_p in outputs:
            lines.append(f"            {out_p.name} <= {out_p.name}_next;")
        lines.append("        end")
        lines.append("    end")
    else:
        lines.append("    always_comb begin")
        for idx, out_p in enumerate(outputs):
            w = out_p.width
            lines.append(f"        {out_p.name} = {w}'d0;")
            if inputs:
                src = inputs[idx % len(inputs)]
                if src.width == w:
                    lines.append(f"        {out_p.name} = {src.name};")
        lines.append("    end")

    lines.append("")
    lines.append("endmodule")
    return "\n".join(lines) + "\n"


def generate_rtl(
    spec: DigitalSpec,
    output_dir: Path,
    llm_hook: LlmHookFn | None = None,
    prompt_context: str | None = None,
) -> list[Path]:
    """Generate clean, synthesizable SystemVerilog RTL file(s) from DigitalSpec."""
    output_dir.mkdir(parents=True, exist_ok=True)
    top = spec.top_module or spec.name
    pmap = _param_dict(spec)

    # 1. Explicit custom RTL override in spec
    if spec.custom_rtl_sv:
        out_path = output_dir / f"{top}.sv"
        out_path.write_text(spec.custom_rtl_sv.strip() + "\n", encoding="utf-8")
        return [out_path]

    # 2. Optional LLM synthesis hook when archetype is custom or hook is supplied
    hook = llm_hook or default_llm_synthesis_hook
    if spec.archetype == "custom":
        hook_files = hook(spec, prompt_context)
        if hook_files:
            written: list[Path] = []
            for fname, content in hook_files.items():
                fpath = output_dir / fname
                fpath.write_text(content.strip() + "\n", encoding="utf-8")
                written.append(fpath)
            return written

    # 3. Parameterized verified SystemVerilog templates
    file_map: dict[str, str] = {}
    if spec.archetype == "adder_sub_7seg":
        file_map[f"{top}.sv"] = _ADDER_SUB_7SEG_SV.render(top_module=top)
    elif spec.archetype == "traffic_fsm":
        file_map[f"{top}.sv"] = _TRAFFIC_FSM_SV.render(
            top_module=top,
            sim_mode=int(pmap.get("SIM_MODE", 0)),
            clk_freq_hz=int(str(pmap.get("CLK_FREQ_HZ", int(spec.clock_freq_mhz * 1_000_000))).replace("_", "")),
            sim_ticks_per_sec=int(pmap.get("SIM_TICKS_PER_SEC", 4)),
            green_sec=int(pmap.get("GREEN_SEC", 6)),
            yellow_sec=int(pmap.get("YELLOW_SEC", 2)),
            ped_sec=int(pmap.get("PED_SEC", 4)),
            all_red_sec=int(pmap.get("ALL_RED_SEC", 1)),
        )
    elif spec.archetype == "uart_fifo_top":
        file_map["sync_fifo.sv"] = _SYNC_FIFO_SV
        file_map["uart_tx.sv"] = _UART_TX_SV
        file_map["uart_rx.sv"] = _UART_RX_SV
        file_map[f"{top}.sv"] = _UART_FIFO_TOP_SV.render(
            top_module=top,
            clk_freq=int(str(pmap.get("CLK_FREQ", int(spec.clock_freq_mhz * 1_000_000))).replace("_", "")),
            baud_rate=int(str(pmap.get("BAUD_RATE", 115200)).replace("_", "")),
        )
    else:
        file_map[f"{top}.sv"] = _render_generic_sync_sv(spec)

    paths: list[Path] = []
    for fname, sv_text in file_map.items():
        p = output_dir / fname
        p.write_text(sv_text.strip() + "\n", encoding="utf-8")
        paths.append(p)
    return paths
